
.worldbar {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  padding: 8px 14px;
  background: var(--c-surface-2);
  border-bottom: 1px solid var(--c-border);
  font-family: var(--font-body);
  font-size: 12px;
}

.worldbar__crest {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--c-primary);
  font-family: var(--font-title);
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 2px;
}

.worldbar__castle {
  color: var(--c-text);
}

.worldbar__item {
  display: flex;
  align-items: center;
  gap: 5px;
  color: var(--c-text-muted);
  white-space: nowrap;
}

.worldbar__item i {
  color: var(--c-primary);
  font-size: 11px;
}

.worldbar__item--feast {
  color: var(--c-accent);
  font-weight: 600;
}

.worldbar__item--feast i {
  color: var(--c-accent);
}
