
.castle {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.castle__section {
  background: var(--c-surface-2);
  border: 1px solid var(--c-border);
  padding: 10px 12px;
  border-radius: 2px;
}

.castle__subtitle {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-title);
  font-size: 13px;
  letter-spacing: 1px;
  color: var(--c-primary);
  margin-bottom: 8px;
  border-bottom: 1px dashed var(--c-border);
  padding-bottom: 4px;
}

.castle__goal {
  font-size: 12px;
  line-height: 1.6;
  color: var(--c-text);
}

.castle__fallen {
  font-size: 12px;
  line-height: 1.6;
  color: var(--c-accent);
}

.castle__log {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 220px;
  overflow-y: auto;
}

.castle__log-item {
  display: flex;
  gap: 7px;
  align-items: baseline;
  font-size: 12px;
  line-height: 1.5;
  color: var(--c-text);
}

.castle__log-bullet {
  flex-shrink: 0;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--c-primary);
  transform: translateY(-1px);
}

.castle__empty {
  font-size: 12px;
  color: var(--c-text-muted);
}
